-- 5.6 Audit revert -------------------------------------------------------

create or replace function public.revert_audit_entry(entry_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  entry public.content_audit_log%rowtype;
  allowed_tables text[] := array[
    'announcements', 'schedule_items', 'prayer_requests',
    'church_profile', 'ministries', 'recurring_meetings',
    'members', 'households', 'member_relationships'
  ];
  cols text;
  vals text;
  set_clause text;
  payload jsonb;
begin
  if not public.is_admin() then
    raise exception 'Acesso negado: apenas admins podem reverter alteracoes.';
  end if;

  select * into entry from public.content_audit_log where id = entry_id;
  if not found then
    raise exception 'Entrada de audit log nao encontrada: %', entry_id;
  end if;

  if not (entry.table_name = any(allowed_tables)) then
    raise exception 'Tabela nao autorizada para revert: %', entry.table_name;
  end if;

  if entry.action = 'INSERT' then
    execute format('delete from public.%I where id = $1', entry.table_name)
      using entry.row_id;
  elsif entry.action = 'UPDATE' then
    payload := entry.old_row;
    if payload is null then
      raise exception 'old_row ausente em UPDATE; impossivel reverter.';
    end if;
    select string_agg(
      format('%I = (jsonb_populate_record(null::public.%I, $1)).%I', key, entry.table_name, key),
      ', '
    )
      into set_clause
      from jsonb_object_keys(payload) as key
      where key <> 'id';
    if set_clause is null then return; end if;
    execute format('update public.%I set %s where id = $2', entry.table_name, set_clause)
      using payload, entry.row_id;
  elsif entry.action = 'DELETE' then
    payload := entry.old_row;
    if payload is null then
      raise exception 'old_row ausente em DELETE; impossivel reverter.';
    end if;
    select
      string_agg(format('%I', key), ', '),
      string_agg(format('(jsonb_populate_record(null::public.%I, $1)).%I', entry.table_name, key), ', ')
      into cols, vals
      from jsonb_object_keys(payload) as key;
    execute format('insert into public.%I (%s) values (%s)', entry.table_name, cols, vals)
      using payload;
  else
    raise exception 'Acao desconhecida: %', entry.action;
  end if;
end;
$$;

-- 5.7 Members helpers ----------------------------------------------------

create or replace function public.find_member_duplicates(
  p_full_name text,
  p_cpf text,
  p_email text,
  p_phone text
)
returns table (
  member_id uuid,
  full_name text,
  score numeric,
  match_reason text
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  phone_digits text := regexp_replace(coalesce(p_phone, ''), '\D+', '', 'g');
begin
  if not public.is_admin() then
    raise exception 'Acesso negado.';
  end if;

  return query
  with candidates as (
    select
      m.id as member_id,
      m.full_name as full_name,
      case
        when p_cpf is not null and p_cpf <> '' and m.cpf = p_cpf then 1.0
        when p_email <> '' and lower(m.email) = lower(p_email) then 0.9
        when phone_digits <> '' and regexp_replace(coalesce(m.phone, ''), '\D+', '', 'g') = phone_digits then 0.85
        when phone_digits <> '' and regexp_replace(coalesce(m.whatsapp, ''), '\D+', '', 'g') = phone_digits then 0.85
        when similarity(m.full_name, coalesce(p_full_name, '')) > 0.7
          then similarity(m.full_name, p_full_name)::numeric
        else 0
      end as score,
      case
        when p_cpf is not null and p_cpf <> '' and m.cpf = p_cpf then 'cpf_match'
        when p_email <> '' and lower(m.email) = lower(p_email) then 'email_match'
        when phone_digits <> '' and regexp_replace(coalesce(m.phone, ''), '\D+', '', 'g') = phone_digits then 'phone_match'
        when phone_digits <> '' and regexp_replace(coalesce(m.whatsapp, ''), '\D+', '', 'g') = phone_digits then 'phone_match'
        when similarity(m.full_name, coalesce(p_full_name, '')) > 0.7 then 'name_similar'
        else null
      end as match_reason
    from public.members m
    where m.deleted_at is null
  )
  select c.member_id, c.full_name, c.score, c.match_reason
  from candidates c
  where c.score > 0
  order by c.score desc
  limit 5;
end;
$$;

